<script setup lang="ts">
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue';
import type {ReconstructionConfig,ReconstructionPreview} from '../../platform/research.ts';
import {pixelStroke} from './pixel-stroke.ts';
type Stroke=NonNullable<ReconstructionConfig['strokes']>[number];
const props=defineProps<{preview:ReconstructionPreview;strokes:Stroke[];disabled?:boolean;frequencyMax?:number;height?:number}>();
const emit=defineEmits<{ 'update:strokes':[Stroke[]];'update:height':[number] }>();
const canvas=ref<HTMLCanvasElement>(),viewport=ref<HTMLDivElement>(),color=ref<0|255>(0),size=ref(12),opacity=ref(100),zoom=ref(1),tool=ref<'brush'|'pan'>('brush'),redo=ref<Stroke[]>([]),message=ref('');
const displayWidth=ref(640),displayHeight=ref(360),autoFit=ref(true),cursor=ref<{x:number;y:number}>();
const audioCanvas=computed(()=>!!props.preview.n_fft),frequencyMax=computed(()=>Math.max(1,Math.min((props.preview.sample_rate??16000)/2,Number(props.frequencyMax)||5000)));
const frequencyFraction=computed(()=>audioCanvas.value?frequencyMax.value/((props.preview.sample_rate??16000)/2):1);
const drawingWidth=computed(()=>audioCanvas.value?Math.round(displayWidth.value):props.preview.width),drawingHeight=computed(()=>audioCanvas.value?Math.round(displayHeight.value):props.preview.height);
const canvasWidth=computed(()=>drawingWidth.value*zoom.value),canvasHeight=computed(()=>drawingHeight.value*zoom.value),brushDiameter=computed(()=>Math.max(1,Math.min(200,Math.round(Number(size.value)||1))));
const scrollLeft=ref(0),scrollTop=ref(0);
const visibleTime=computed(()=>{const duration=props.preview.duration??0;return [scrollLeft.value/canvasWidth.value*duration,Math.min(duration,(scrollLeft.value+displayWidth.value+4)/canvasWidth.value*duration)];});
const visibleFrequency=computed(()=>[frequencyMax.value*(1-scrollTop.value/canvasHeight.value),Math.max(0,frequencyMax.value*(1-(scrollTop.value+displayHeight.value+4)/canvasHeight.value))]);
function scrolled(){scrollLeft.value=viewport.value?.scrollLeft??0;scrollTop.value=viewport.value?.scrollTop??0;}
function leave(){if(!current)cursor.value=undefined;}
let base:HTMLImageElement|undefined,cache:HTMLCanvasElement|undefined,overlay:HTMLCanvasElement|undefined,currentRaster:HTMLCanvasElement|undefined,currentPoints=0,current:Stroke|undefined,pointer:number|undefined,last:{x:number;y:number;sx:number;sy:number}|undefined,observer:ResizeObserver|undefined,disposed=false;
function strokePoint(s:Stroke,p:{x:number;y:number}){return {x:p.x*((s.canvas_width??props.preview.width)-1),y:p.y*((s.canvas_height??props.preview.height)-1)};}
function drawStroke(ctx:CanvasRenderingContext2D,s:Stroke){if(s.size_unit==='px'){const p=pixelStroke(ctx.canvas.width,ctx.canvas.height,s),image=ctx.createImageData(p.width,p.height);for(let i=0;i<p.mask.length;i++)if(p.mask[i]){image.data[i*4]=image.data[i*4+1]=image.data[i*4+2]=s.color;image.data[i*4+3]=255;}ctx.putImageData(image,p.left,p.top);return;}ctx.strokeStyle=ctx.fillStyle=s.color===0?'#000':'#fff';ctx.lineWidth=Math.max(1,Math.round(s.size/2))*2;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>{const {x,y}=strokePoint(s,p);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);});ctx.stroke();if(s.points.length===1){const p=strokePoint(s,s.points[0]);ctx.beginPath();ctx.arc(p.x,p.y,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}}
function composite(ctx:CanvasRenderingContext2D,image:HTMLCanvasElement,s:Stroke){const fraction=s.frequency_fraction??1;ctx.globalAlpha=s.opacity;ctx.drawImage(image,0,ctx.canvas.height*(1-fraction/frequencyFraction.value),ctx.canvas.width,ctx.canvas.height*fraction/frequencyFraction.value);ctx.globalAlpha=1;}
function layer(ctx:CanvasRenderingContext2D,s:Stroke){if(!overlay)return;overlay.width=s.canvas_width??props.preview.width;overlay.height=s.canvas_height??props.preview.height;drawStroke(overlay.getContext('2d')!,s);composite(ctx,overlay,s);}
function render(){const c=canvas.value;if(!c||!cache)return;const g=c.getContext('2d')!;g.drawImage(cache,0,0);if(current&&overlay){if(!currentRaster){currentRaster=document.createElement('canvas');currentRaster.width=current.canvas_width??props.preview.width;currentRaster.height=current.canvas_height??props.preview.height;currentPoints=0;}if(currentPoints!==current.points.length){overlay.width=currentRaster.width;overlay.height=currentRaster.height;drawStroke(overlay.getContext('2d')!,{...current,points:current.points.slice(Math.max(0,currentPoints-1))});currentRaster.getContext('2d')!.drawImage(overlay,0,0);currentPoints=current.points.length;}composite(g,currentRaster,current);}}
function rebuild(){if(!base?.complete||!base.naturalWidth||!canvas.value)return;const c=canvas.value;c.width=drawingWidth.value;c.height=drawingHeight.value;cache=document.createElement('canvas');overlay=document.createElement('canvas');cache.width=overlay.width=c.width;cache.height=overlay.height=c.height;const g=cache.getContext('2d')!;g.drawImage(base,0,base.naturalHeight*(1-frequencyFraction.value),base.naturalWidth,base.naturalHeight*frequencyFraction.value,0,0,c.width,c.height);for(const s of props.strokes)layer(g,s);render();}
async function load(){current=undefined;currentRaster=undefined;pointer=undefined;last=undefined;cursor.value=undefined;redo.value=[];autoFit.value=true;await nextTick();if(disposed)return;fit();if(viewport.value){viewport.value.scrollLeft=0;viewport.value.scrollTop=0;}const img=new Image();img.onload=()=>{if(disposed||img!==base)return;rebuild();};base=img;img.src='data:image/png;base64,'+props.preview.image_base64;}
watch(()=>props.preview,load);watch(()=>props.strokes,rebuild);
watch(()=>props.frequencyMax,()=>{cursor.value=undefined;if(viewport.value)viewport.value.scrollTop=0;rebuild();});
watch([drawingWidth,drawingHeight],rebuild);
function point(e:PointerEvent){const r=canvas.value!.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))};}
function down(e:PointerEvent){if(props.disabled||e.button!==0||pointer!==undefined)return;pointer=e.pointerId;canvas.value!.setPointerCapture(e.pointerId);const r=canvas.value!.getBoundingClientRect();cursor.value={x:e.clientX-r.left,y:e.clientY-r.top};message.value='';if(tool.value==='pan'||e.shiftKey){const v=viewport.value!;last={x:e.clientX,y:e.clientY,sx:v.scrollLeft,sy:v.scrollTop};return;}if(props.strokes.length>=256||props.strokes.reduce((n,s)=>n+s.points.length,0)>=8192){message.value='笔迹已达上限，请撤销部分笔迹。';pointer=undefined;return;}current={color:color.value,size:brushDiameter.value,size_unit:'px',...(audioCanvas.value?{canvas_width:drawingWidth.value,canvas_height:drawingHeight.value,frequency_fraction:frequencyFraction.value}:{}),opacity:opacity.value/100,points:[point(e)]};render();}
function move(e:PointerEvent){const r=canvas.value!.getBoundingClientRect();cursor.value={x:e.clientX-r.left,y:e.clientY-r.top};if(pointer!==e.pointerId)return;if(last){viewport.value!.scrollLeft=last.sx+last.x-e.clientX;viewport.value!.scrollTop=last.sy+last.y-e.clientY;return;}if(!current)return;const p=point(e),q=current.points.at(-1)!;if(Math.hypot((p.x-q.x)*drawingWidth.value,(p.y-q.y)*drawingHeight.value)<.8)return;if(current.points.length>=4096||props.strokes.reduce((n,s)=>n+s.points.length,0)+current.points.length>=8192){message.value='本次笔迹已达上限，请结束当前笔画。';return;}current.points.push(p);render();}
function finish(e:PointerEvent){if(pointer!==e.pointerId)return;if(current){const s=current;current=undefined;currentRaster=undefined;redo.value=[];emit('update:strokes',[...props.strokes,s]);}last=undefined;pointer=undefined;if(canvas.value?.hasPointerCapture(e.pointerId))canvas.value.releasePointerCapture(e.pointerId);}
function undo(){if(props.disabled||current||!props.strokes.length)return;redo.value.push(props.strokes.at(-1)!);emit('update:strokes',props.strokes.slice(0,-1));}
function forward(){if(props.disabled||current)return;const s=redo.value.pop();if(s)emit('update:strokes',[...props.strokes,s]);}
function fit(){zoom.value=audioCanvas.value?1:Math.min(8,displayWidth.value/drawingWidth.value,displayHeight.value/drawingHeight.value);autoFit.value=true;cursor.value=undefined;}
function scale(value:number){zoom.value=Math.max(audioCanvas.value?1:.01,Math.min(8,value));autoFit.value=false;cursor.value=undefined;}
function wheel(e:WheelEvent){if(!e.ctrlKey)return;e.preventDefault();scale(zoom.value*(e.deltaY<0?1.25:.8));}
function key(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?forward():undo();}}
onMounted(()=>{observer=new ResizeObserver(entries=>{if(entries[0].contentRect.width<=0||entries[0].contentRect.height<=0)return;displayWidth.value=Math.max(2,(viewport.value?.clientWidth??640)-4);displayHeight.value=Math.max(2,(viewport.value?.clientHeight??360)-4);if(audioCanvas.value){const height=viewport.value!.offsetHeight;if(height!==props.height)emit('update:height',height);}if(autoFit.value)fit();});observer.observe(viewport.value!);void load();});
onUnmounted(()=>{disposed=true;observer?.disconnect();});
</script>
<template><section class="spectral-editor" aria-label="频谱绘图编辑器" @keydown="key">
 <div class="paint-tools"><div class="spectral-tool-group"><button :aria-pressed="tool==='brush'&&color===0" @click="tool='brush';color=0">黑色画笔</button><button :aria-pressed="tool==='brush'&&color===255" @click="tool='brush';color=255">白色画笔</button><button :aria-pressed="tool==='pan'" @click="tool='pan'">拖动画面</button></div>
 <label>直径（px） <input aria-label="画笔粗细" type="range" min="1" max="200" v-model.number="size"/><input aria-label="画笔直径（像素）" type="number" min="1" max="200" step="1" v-model.number="size" @change="size=Math.max(1,Math.min(200,Math.round(Number(size)||1)))"/></label><label>不透明度 <input aria-label="画笔不透明度" type="range" min="0" max="100" v-model.number="opacity"/><output>{{opacity}}%</output></label>
 <div class="spectral-tool-group"><button aria-label="撤销笔迹" @click="undo" :disabled="disabled||!strokes.length">撤销</button><button aria-label="重做笔迹" @click="forward" :disabled="disabled||!redo.length">重做</button><button @click="scale(zoom/1.25)" :disabled="zoom<=(audioCanvas?1:.01)">−</button><output>{{Math.round(zoom*100)}}%</output><button @click="scale(zoom*1.25)" :disabled="zoom>=8">＋</button><button @click="scale(1)">100%</button><button @click="fit">适合窗口</button></div></div>
 <div class="axis-note"><span>高频 ↑</span><span>时间 → · 黑色增强，白色减弱</span><span>{{strokes.length}} 笔</span></div>
 <div :class="{'audio-plot':audioCanvas}"><div v-if="audioCanvas" class="frequency-ruler" aria-label="频率轴"><span>{{Math.round(visibleFrequency[0])}} Hz</span><span>{{Math.round((visibleFrequency[0]+visibleFrequency[1])/2)}}</span><span>{{Math.round(visibleFrequency[1])}}</span></div><div ref="viewport" class="paint-viewport" :class="{'audio-viewport':audioCanvas}" :style="audioCanvas?{height:Math.max(180,Math.min(800,Number(height)||320))+'px'}:undefined" @wheel="wheel" @scroll="scrolled"><div class="paint-stage" :style="{width:Math.max(displayWidth,canvasWidth)+'px',height:Math.max(displayHeight,canvasHeight)+'px'}"><div class="paint-surface" :style="{width:canvasWidth+'px',height:canvasHeight+'px'}"><canvas ref="canvas" :data-source-width="preview.width" :data-source-height="preview.height" tabindex="0" aria-label="可缩放频谱画布" :class="{panning:tool==='pan'}" :style="{width:canvasWidth+'px',height:canvasHeight+'px'}" @pointerdown.prevent="down" @pointermove="move" @pointerleave="leave" @pointerup="finish" @pointercancel="finish" @lostpointercapture="finish"/><span v-if="cursor&&tool==='brush'&&!disabled" class="brush-cursor" :style="{left:cursor.x+'px',top:cursor.y+'px',width:brushDiameter*zoom+'px',height:brushDiameter*zoom+'px'}"/></div></div></div></div>
 <div v-if="audioCanvas" class="time-ruler" aria-label="时间轴"><span v-for="i in 5" :key="i">{{(visibleTime[0]+(visibleTime[1]-visibleTime[0])*(i-1)/4).toFixed(3)}}{{i===5?' s':''}}</span></div>
 <p class="muted">{{audioCanvas?'可拖动图窗右下角调整高度。':'按原图像素设置直径（'+drawingWidth+' × '+drawingHeight+' px）。'}}Ctrl + 滚轮缩放 · Shift + 拖动平移 · Ctrl + Z 撤销 · Ctrl + Shift + Z 重做</p><p v-if="message" role="status">{{message}}</p>
</section></template>
<style scoped>
.spectral-editor{min-width:0}.paint-tools,.spectral-tool-group{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.paint-tools{gap:8px;margin-bottom:8px}.paint-tools label{display:flex;align-items:center;gap:5px;white-space:nowrap}.paint-tools input{width:78px;min-height:18px}.paint-tools output{min-width:3ch;text-align:center}.paint-tools button[aria-pressed=true]{background:var(--selection);border-color:var(--accent);color:var(--accent)}.paint-viewport{overflow:auto;height:min(44vh,440px);min-height:260px;scrollbar-gutter:stable;background:var(--app);border:1px solid var(--border);border-radius:var(--radius);overscroll-behavior:contain}.paint-stage{display:flex;align-items:center;justify-content:center}.paint-surface{position:relative;flex-shrink:0}.paint-viewport canvas{display:block;touch-action:none;cursor:crosshair;max-width:none}.paint-viewport canvas.panning{cursor:grab}.brush-cursor{position:absolute;pointer-events:none;box-sizing:border-box;border:1px solid #fff;outline:1px solid #000;border-radius:50%;transform:translate(-50%,-50%)}.axis-note{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:.857143rem;margin-bottom:4px}.muted{font-size:.857143rem;margin:6px 0 0}
.audio-plot{display:grid;grid-template-columns:64px minmax(0,1fr);gap:6px}.audio-viewport{min-height:180px;max-height:800px;resize:vertical}.frequency-ruler{display:flex;flex-direction:column;justify-content:space-between;align-items:flex-end;padding:2px 0;color:var(--muted);font-size:.857143rem;font-variant-numeric:tabular-nums}.time-ruler{display:flex;justify-content:space-between;margin:4px 0 0 70px;color:var(--muted);font-size:.857143rem;font-variant-numeric:tabular-nums}
</style>
